html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form tr { page-break-inside: avoid; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 12px 0 6px; }
.lpl-form .rule { min-height: 34px; white-space: pre-wrap; border: 1px solid #000; padding: 4px 6px; margin: 0 0 12px; }
.lpl-form .scores td, .lpl-form .scores th { text-align: center; }
.lpl-form .scores td { font-weight: bold; }
.lpl-form .right { text-align: right; }
.lpl-form .muted { color: #444; font-size: 10.5px; }
.lpl-form table.bare { border: none; }
.lpl-form table.bare > tbody > tr > td, .lpl-form table.bare > tr > td { border: none; padding: 0; }
.lpl-form .pre { white-space: pre-wrap; }
.lpl-form .nowrap { white-space: nowrap; }
.lpl-form .grid td, .lpl-form .grid th { text-align: center; vertical-align: middle; height: 30px; }
.lpl-form .grid td { width: 27%; font-size: 10.5px; }
.lpl-form .grid .axis { width: 19%; font-weight: bold; background: #f2f2f2; }
.lpl-form .grid .here { background: #bfbfbf; font-weight: bold; font-size: 11.5px; }
.lpl-form .sign td { border: none; padding: 14px 6px 0 0; width: 33%; }
.lpl-form .sign .line { border-top: 1px solid #000; padding-top: 3px; }
</style>
{%- set sees_boxes = doc.has_permlevel_access_to("box") -%}
<div class="lpl-form">
<h3>Talent Card</h3>
<table>
<tr><th style="width:18%">Employee</th><td>{{ v(doc.employee_name) }}</td>
<th style="width:17%">Designation</th><td>{{ v(doc.designation) }}</td></tr>
<tr><th>Department</th><td>{{ v(doc.department) }}</td><th>Plant</th><td>{{ v(doc.branch) }}</td></tr>
<tr><th>Grade</th><td>{{ v(doc.grade) }}</td>
<th>Talent Review</th><td>{{ v(frappe.db.get_value("Talent Review", doc.talent_review, "title")
  or doc.talent_review) }}</td></tr>
<tr><th>Status</th><td>{{ v(doc.status) }}</td><th>Finalised On</th><td>{{ day(doc.finalised_on) }}</td></tr>
</table>

{%- if sees_boxes and doc.box %}
<h4>Nine-Box Placement</h4>
<table class="bare"><tr>
<td style="width:56%;padding-right:12px">
<table class="grid">
{%- for line in talent_grid() %}
<tr><th class="axis">{{ ["High", "Moderate", "Low"][loop.index0] }} potential</th>
{%- for cell in line %}
<td class="{{ 'here' if cell.box == doc.box else '' }}">{{ cell.box }} {{ v(cell.name) }}</td>
{%- endfor %}</tr>
{%- endfor %}
<tr><th class="axis"></th><th>Low</th><th>Meeting</th><th>Exceeding</th></tr>
<tr><th class="axis"></th><th colspan="3">Performance, year to date</th></tr>
</table>
</td>
<td style="width:44%">
<table>
<tr><th style="width:42%">Box</th><td><b>{{ doc.box }} {{ v(doc.box_name) }}</b></td></tr>
<tr><th>Top Talent</th><td>{{ "Yes" if doc.top_talent else "No" }}</td></tr>
<tr><th>Default Action</th><td>{{ v(doc.default_action) }}</td></tr>
<tr><th>Suggested Decision</th><td>{{ v(doc.suggested_decision) }}</td></tr>
{%- if doc.submitted_box and doc.submitted_box != doc.box %}
<tr><th>Moved in Calibration</th><td>From box {{ doc.submitted_box }}. {{ v(doc.calibration_reason) }}</td></tr>
{%- endif %}
</table>
</td>
</tr></table>
{%- endif %}

<h4>Performance, Year to Date</h4>
<table>
<tr><th style="width:22%">Year to Date Score</th><td>{{ num(doc.performance_score) }}{{ "%" if doc.performance_score else "" }}</td>
<th style="width:22%">Rating</th><td>{{ v(doc.appraisal_band) }}{% if sees_boxes and doc.performance_band %} ({{ v(doc.performance_band) }}){% endif %}</td></tr>
<tr><th>Latest Appraisal</th><td>{{ v(doc.appraisal) }}</td>
<th>Management's Decision</th><td>{{ v(doc.management_decision) }}</td></tr>
<tr><th>On an Improvement Plan</th><td>{{ "Yes" if doc.on_pip else "No" }}{% if doc.improvement_plan %} ({{ v(doc.improvement_plan) }}){% endif %}</td>
<th>Performance Review</th><td>{{ v(doc.performance_review) }}</td></tr>
</table>
{%- if doc.quarter_results %}
<table>
<tr><th style="width:10%">Quarter</th><th>Appraisal</th><th style="width:12%">Section A</th><th style="width:12%">Section B</th>
<th style="width:11%">Total</th><th style="width:15%">Rating</th><th style="width:14%">Status</th></tr>
{%- for row in doc.quarter_results %}
<tr><td>{{ v(row.quarter) }}</td><td>{{ v(row.appraisal) }}</td><td class="right">{{ num(row.section_a) }}</td>
<td class="right">{{ num(row.section_b) }}</td><td class="right">{{ num(row.total) }}</td><td>{{ v(row.band) }}</td>
<td>{{ v(row.status) }}</td></tr>
{%- endfor %}
</table>
{%- endif %}

<h4>Potential</h4>
<table class="scores">
<tr><th>Ability</th><th>Aspiration</th><th>Engagement</th><th>Potential out of 100</th>
{%- if sees_boxes %}<th>Band</th><th>After Calibration</th>{% endif %}</tr>
<tr><td>{{ num(doc.ability) }} / 10</td><td>{{ num(doc.aspiration) }} / 10</td><td>{{ num(doc.engagement) }} / 10</td>
<td>{{ num(doc.potential_score) }}</td>
{%- if sees_boxes %}<td>{{ v(doc.potential_band) }}</td><td>{{ v(doc.calibrated_potential) }}</td>{% endif %}</tr>
</table>
{%- if doc.competencies %}
<table>
<tr><th>Competency or Factor</th><th style="width:13%">Level out of 10</th><th style="width:11%">Times Rated</th>
<th style="width:18%">From Appraisal</th><th style="width:24%">Remarks</th></tr>
{%- for row in doc.competencies %}
<tr><td>{{ v(row.competency) }}</td><td class="right">{{ num(row.level) }}</td><td class="right">{{ row.times or "" }}</td>
<td>{{ v(row.appraisal) }}</td><td class="pre">{{ v(row.remarks) }}</td></tr>
{%- endfor %}
<tr><th class="right">Competency Average</th><td class="right"><b>{{ num(doc.competency_average) }}</b></td><td colspan="3"></td></tr>
</table>
{%- endif %}
{%- if doc.rationale %}
<p><b>Line manager's rationale</b></p>
<div class="rule">{{ v(doc.rationale) }}</div>
{%- endif %}

<h4>Retention</h4>
<table>
<tr><th style="width:22%">Flight Risk</th><td>{{ v(doc.flight_risk) }}</td><th style="width:22%">Impact of Loss</th>
<td>{{ v(doc.impact_of_loss) }}</td></tr>
{%- if doc.risk_notes %}<tr><th>Risk Notes</th><td colspan="3" class="pre">{{ v(doc.risk_notes) }}</td></tr>{% endif %}
</table>

<h4>Development</h4>
{%- if doc.themes %}
<table>
<tr><th style="width:4%">#</th><th style="width:32%">Theme</th><th>Why</th><th style="width:20%">Sent to L&amp;D</th></tr>
{%- for row in doc.themes %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.theme) }}</td><td class="pre">{{ v(row.why) }}</td><td>{{ v(row.training_requisition) }}</td></tr>
{%- endfor %}
</table>
{%- endif %}
{%- set progress = talent_plan_progress(doc.development_plan) if doc.development_plan else None %}
<p><b>Development plan:</b> {{ v(doc.development_plan) or "none drawn up yet" }}
{%- if progress and progress.actions %}, {{ progress.done }} of {{ progress.actions }} actions done{% if progress.late %}, {{ progress.late }} past their date{% endif %}{% endif %}</p>

<table class="sign"><tr>
<td><div class="line">Line Manager: {{ who(doc.submitted_by) }}</div><span class="muted">Date {{ day(doc.submitted_on) }}</span></td>
<td><div class="line">Calibrated by: {{ who(doc.calibrated_by) }}</div><span class="muted">Date {{ day(doc.calibrated_on) }}</span></td>
<td><div class="line">Talent Council: {{ who(doc.finalised_by) }}</div><span class="muted">Date {{ day(doc.finalised_on) }}</span></td>
</tr></table>
</div>
